  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_aid_request_item` (`item_id`),
  KEY `fk_aid_request_submitter` (`submitted_by`),
  KEY `fk_aid_request_reviewer` (`reviewed_by`),
